mapper.insert:
INSERT INTO MES_GSQ_SCHEDULE_RESULT ( SCHEDULE_DATE, TQ_BATCH_NO, BATCH_NO, ORDER_NO, STEEL_TYPE, STEEL_RING_CODE, MATERIAL_CODE, MACHINE_CODE, EMBRYO_SPEC_DESC, UNIT_CONSUME, STOCK_QTY, SUPPLY_TIME, NIGHT_PLAN_QTY, NIGHT_PRODUCE_ORDER, NIGHT_SYS_ANALYSIS, NIGHT_HAND_ANALYSIS, NIGHT_REMARK, DAY_PLAN_QTY, DAY_PRODUCE_ORDER, DAY_SYS_ANALYSIS, DAY_HAND_ANALYSIS, DAY_REMARK, MID_PLAN_QTY, MID_PRODUCE_ORDER, MID_SYS_ANALYSIS, MID_HAND_ANALYSIS, MID_REMARK, REMARK, DATA_VERSION, COMPANY_CODE, FACTORY_CODE ) SELECT * FROM (
SELECT #{item.scheduleDate} AS SCHEDULE_DATE, #{item.tqBatchNo} AS TQ_BATCH_NO, #{item.batchNo} AS BATCH_NO, #{item.orderNo} AS ORDER_NO, #{item.steelType} AS STEEL_TYPE, #{item.steelRingCode} AS STEEL_RING_CODE, #{item.materialCode} AS MATERIAL_CODE, #{item.machineCode} AS MACHINE_CODE, #{item.embryoSpecDesc} AS EMBRYO_SPEC_DESC, #{item.unitConsume} AS UNIT_CONSUME, #{item.stockQty} AS STOCK_QTY, #{item.supplyTime} AS SUPPLY_TIME, #{item.nightPlanQty} AS NIGHT_PLAN_QTY, #{item.nightProduceOrder} AS NIGHT_PRODUCE_ORDER, #{item.nightSysAnalysis} AS NIGHT_SYS_ANALYSIS, #{item.nightHandAnalysis} AS NIGHT_HAND_ANALYSIS, #{item.nightSysAnalysis} AS NIGHT_REMARK, #{item.dayPlanQty} AS DAY_PLAN_QTY, #{item.dayProduceOrder} AS DAY_PRODUCE_ORDER, #{item.daySysAnalysis} AS DAY_SYS_ANALYSIS, #{item.dayHandAnalysis} AS DAY_HAND_ANALYSIS, #{item.daySysAnalysis} AS DAY_REMARK, #{item.midPlanQty} AS MID_PLAN_QTY, #{item.midProduceOrder} AS MID_PRODUCE_ORDER, #{item.midSysAnalysis} AS MID_SYS_ANALYSIS, #{item.midHandAnalysis} AS MID_HAND_ANALYSIS, #{item.midSysAnalysis} AS MID_REMARK, #{item.remark} AS REMARK, #{item.dataVersion} AS DATA_VERSION, #{item.companyCode} AS COMPANY_CODE, #{item.factoryCode} AS FACTORY_CODE
) AS t WHERE NOT EXISTS ( SELECT 1 FROM MES_GSQ_SCHEDULE_RESULT WHERE SCHEDULE_DATE = t.SCHEDULE_DATE AND MACHINE_CODE = t.MACHINE_CODE AND STEEL_RING_CODE = t.STEEL_RING_CODE )

mapper.delete:
DELETE FROM MES_GSQ_SCHEDULE_RESULT
WHERE SCHEDULE_DATE = #{scheduleDate}
AND DATA_VERSION = #{dataVersion}

mapper.select:
SELECT SCHEDULE_DATE, MACHINE_CODE, STEEL_RING_CODE
FROM MES_GSQ_SCHEDULE_RESULT
WHERE

    (SCHEDULE_DATE = #{item.scheduleDate}
     AND MACHINE_CODE = #{item.machineCode}
     AND STEEL_RING_CODE = #{item.steelRingCode})

mapper.delete:
DELETE FROM MES_GSQ_SCHEDULE_RESULT WHERE

    (SCHEDULE_DATE = #{item.scheduleDate}
     AND MACHINE_CODE = #{item.machineCode}
     AND STEEL_RING_CODE = #{item.steelRingCode})
